import React, { useState } from "react";
import { motion } from "framer-motion";
import { Mail, Github, Linkedin, MapPin, Send, Check } from "lucide-react";
import emailjs from "@emailjs/browser";
import { personalInfo } from "../data/mock";
import { useToast } from "../hooks/use-toast";

// ─── EmailJS config ──────────────────────────────────────────────
// 1. Sign up free at https://www.emailjs.com
// 2. Create a Service (Gmail) → copy the Service ID below
// 3. Create a Template with variables: {{from_name}}, {{from_email}}, {{message}}
//    Set "To Email" in the template to pavithrasugumar28@gmail.com
// 4. Copy your Public Key from Account → API Keys
const EMAILJS_SERVICE_ID  = "service_erm1ebi";   // e.g. "service_abc123"
const EMAILJS_TEMPLATE_ID = "template_wm23npf";  // e.g. "template_xyz456"
const EMAILJS_PUBLIC_KEY  = "2aMOZDz0_9DYwa1kc";   // e.g. "aBcDeFgHiJkLmNoP"
// ────────────────────────────────────────────────────────────────────────────────

const Contact = () => {
  const { toast } = useToast();
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [sent, setSent] = useState(false);
  const [sending, setSending] = useState(false);

  const handleChange = (e) =>
    setForm((f) => ({ ...f, [e.target.name]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.message) {
      toast({ title: "Almost there…", description: "Please fill all the fields." });
      return;
    }

    setSending(true);
    try {
      await emailjs.send(
        EMAILJS_SERVICE_ID,
        EMAILJS_TEMPLATE_ID,
        {
          from_name:  form.name,
          from_email: form.email,
          message:    form.message,
        },
        EMAILJS_PUBLIC_KEY
      );
      setSent(true);
      toast({ title: "Note received ✨", description: "Thanks for writing — I’ll reply soon." });
      setTimeout(() => {
        setSent(false);
        setForm({ name: "", email: "", message: "" });
      }, 3000);
    } catch (err) {
      console.error("EmailJS error:", err);
      toast({ title: "Oops!", description: "Couldn’t send your note. Please try again." });
    } finally {
      setSending(false);
    }
  };

  return (
    <section id="contact" className="relative py-28 md:py-36 overflow-hidden bg-[#F3EFE7]">
      <div className="absolute inset-0 paper-texture pointer-events-none"></div>

      <div className="relative max-w-6xl mx-auto px-6 md:px-10">
        <div className="flex items-end gap-4 mb-6">
          <span className="font-caveat text-5xl text-[#A8C9C1] rotate-[-4deg] inline-block">page 07</span>
          <div className="h-[2px] flex-1 bg-[#1F2937]/15 mb-3"></div>
          <span className="text-xs tracking-[0.2em] uppercase text-[#1F2937]/50">the last page</span>
        </div>

        <div className="grid md:grid-cols-12 gap-10 md:gap-14">
          {/* Left: notebook style contact form */}
          <motion.div
            initial={{ opacity: 0, y: 30, rotate: -1.5 }}
            whileInView={{ opacity: 1, y: 0, rotate: -1 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.7 }}
            className="md:col-span-7 relative"
          >
            <div className="absolute -top-4 left-14 w-28 h-6 bg-[#E07856]/70 rotate-[-6deg] shadow-sm"></div>

            <div
              className="relative bg-[#FFFCF5] p-8 md:p-10 shadow-[8px_10px_30px_-10px_rgba(31,41,55,0.3)] border border-[#1F2937]/10"
              style={{
                backgroundImage:
                  "repeating-linear-gradient(to bottom, transparent 0 31px, rgba(31,41,55,0.08) 31px 32px)"
              }}
            >
              <h2 className="font-caveat text-4xl md:text-5xl text-[#1F2937] mb-2">
                Write me a note
              </h2>
              <p className="text-sm text-[#1F2937]/60 mb-6">
                Collaborations, internships, random ideas — I’m all ears.
              </p>

              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <label className="block text-xs uppercase tracking-widest text-[#1F2937]/60 mb-1">
                    Your name
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={form.name}
                    onChange={handleChange}
                    className="w-full bg-transparent border-b-2 border-[#1F2937]/30 focus:border-[#E07856] outline-none py-2 text-[#1F2937] placeholder:text-[#1F2937]/40 transition-colors"
                    placeholder="e.g. Aditi"
                  />
                </div>
                <div>
                  <label className="block text-xs uppercase tracking-widest text-[#1F2937]/60 mb-1">
                    Your email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={form.email}
                    onChange={handleChange}
                    className="w-full bg-transparent border-b-2 border-[#1F2937]/30 focus:border-[#E07856] outline-none py-2 text-[#1F2937] placeholder:text-[#1F2937]/40 transition-colors"
                    placeholder="name@somewhere.com"
                  />
                </div>
                <div>
                  <label className="block text-xs uppercase tracking-widest text-[#1F2937]/60 mb-1">
                    What’s on your mind?
                  </label>
                  <textarea
                    name="message"
                    rows={4}
                    value={form.message}
                    onChange={handleChange}
                    className="w-full bg-transparent border-b-2 border-[#1F2937]/30 focus:border-[#E07856] outline-none py-2 text-[#1F2937] placeholder:text-[#1F2937]/40 resize-none transition-colors"
                    placeholder="Tell me about it…"
                  />
                </div>

                <button
                  type="submit"
                  className="inline-flex items-center gap-2 px-5 py-3 bg-[#1F2937] text-[#F8F6F2] text-sm font-medium shadow-[4px_4px_0px_0px_#E07856] hover:shadow-[2px_2px_0px_0px_#E07856] hover:translate-x-[2px] hover:translate-y-[2px] transition-all duration-200"
                >
                  {sent ? <Check size={16} /> : <Send size={14} />}
                  {sent ? "Note delivered" : sending ? "Sending…" : "Send note"}
                </button>
              </form>
            </div>
          </motion.div>

          {/* Right: contact card */}
          <motion.div
            initial={{ opacity: 0, y: 30, rotate: 2 }}
            whileInView={{ opacity: 1, y: 0, rotate: 1.5 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.7, delay: 0.1 }}
            className="md:col-span-5 space-y-6"
          >
            <div className="relative bg-[#E6C068]/90 p-7 shadow-[5px_6px_20px_-6px_rgba(31,41,55,0.3)] border-2 border-[#1F2937]">
              <div className="absolute -top-3 -right-3 w-20 h-6 bg-[#A8C9C1]/80 rotate-[12deg]"></div>
              <p className="text-[10px] uppercase tracking-[0.2em] text-[#1F2937]/70 mb-2">
                from the desk of
              </p>
              <h3 className="font-caveat text-4xl text-[#1F2937] mb-4">{personalInfo.fullName}</h3>

              <ul className="space-y-3 text-sm text-[#1F2937]">
                <li className="flex items-center gap-3">
                  <Mail size={16} className="shrink-0" />
                  <a href={`mailto:${personalInfo.email}`} className="hover:underline break-all">
                    {personalInfo.email}
                  </a>
                </li>
                <li className="flex items-center gap-3">
                  <MapPin size={16} className="shrink-0" />
                  {personalInfo.location}
                </li>
                <li className="flex items-center gap-3">
                  <Github size={16} className="shrink-0" />
                  <a
                    href={personalInfo.github}
                    target="_blank"
                    rel="noreferrer"
                    className="hover:underline break-all"
                  >
                    github.com/pavithrasugumar-28
                  </a>
                </li>
                <li className="flex items-center gap-3">
                  <Linkedin size={16} className="shrink-0" />
                  <a
                    href={personalInfo.linkedin}
                    target="_blank"
                    rel="noreferrer"
                    className="hover:underline break-all"
                  >
                    in/pavithrasugumar
                  </a>
                </li>
              </ul>
            </div>

            <div className="bg-[#FFFCF5] border-l-4 border-[#A8C9C1] p-5 shadow-md rotate-[-1deg]">
              <p className="font-caveat text-2xl text-[#1F2937] leading-tight">
                “I read every message.
                <br />Yes, even the long ones.”
              </p>
              <p className="text-xs text-[#1F2937]/60 mt-2 uppercase tracking-widest">
                — promise
              </p>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Contact;
